        begin
            reference_number=base;divisor=1;
            for(ci=1;ci<chars;ci=ci+1)divisor=divisor*10;
            for(ci=0;ci<chars;ci=ci+1)begin
                reference_number[287-(start+ci)*9 -: 9]=48+(value/divisor)%10;
