        begin
            case(midi%12)
                0:pc="C "; 1:pc="C#"; 2:pc="D "; 3:pc="D#";
                4:pc="E "; 5:pc="F "; 6:pc="F#"; 7:pc="G ";
                8:pc="G#"; 9:pc="A "; 10:pc="A#"; 11:pc="B ";
